DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEURGAL' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEURGAL_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_1','The Urgal[NEWLINE]Snapshot-based melee timing attacks[NEWLINE]Domination[NEWLINE][NEWLINE]Build and position a complete eligible melee army, then spend a scarce bottle when several useful attacks are ready. Strength II is an attacking window for the current snapshot, not a permanent army upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_2','Develop food, Production, resources and supporting ranged units. Preserve the initial potion until a real objective is reachable. The iron-free Rusher helps the early plan, but the economy still has to build and maintain the force.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_3','Stage the existing unembarked melee attackers before drinking. Use ranged fire, siege where appropriate, and controlled paths to maximize productive attacks during the short window. Newly created units do not join that already committed snapshot.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_4','Keep a second line and a plan for Aftertaste. Save later bottles for important technologies or fronts rather than using one whenever it becomes available. Normal upgrades preserve only an eligible participant''s remaining deadline.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_5','- The attack bonus applies to eligible melee attacks against units and cities.[NEWLINE]- Stored bottles allow deliberate campaign timing.[NEWLINE]- A positioned mixed army can combine boosted finishers with ordinary ranged and siege support.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_6','- The bonus does not improve defense, ranged attacks, ships or aircraft.[NEWLINE]- Newly trained or acquired units cannot enter the current snapshot.[NEWLINE]- The attack window is finite, and Aftertaste blocks immediate reuse.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_7','- Withdraw vulnerable units, use ranged pressure and force long approaches during the window.[NEWLINE]- Defend through the deadline and counterattack after it expires.[NEWLINE]- Attack the production and staging base before the eligible army is ready.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_8','- Drinking while the army is still several turns from contact.[NEWLINE]- Expecting new reinforcements, ranged units or ships to receive the current bonus.[NEWLINE]- Treating Aftertaste as a direct combat penalty rather than a restriction on drinking again.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: A concentrated early strike can punish exposed cities whose owner has prioritized settlement and infrastructure.[NEWLINE][NEWLINE]Viltrum: A well-stocked force can exploit the Scourge''s severe population, survivor and production vulnerability.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: A prepared Toll and territorial line can buy the time needed to exhaust a limited potion window.[NEWLINE][NEWLINE]The Threshold Court: A maintained House network can reinforce a threatened city while the attacking snapshot''s clock keeps running.');
