INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_BACKGROUND','Build and position a complete eligible melee army, then spend a scarce bottle when several useful attacks are ready. Strength II is an attacking window for the current snapshot, not a permanent army upgrade.');
