INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_STRATEGY','Build and position a complete eligible melee army, then spend a scarce bottle when several useful attacks are ready. Strength II is an attacking window for the current snapshot, not a permanent army upgrade.[NEWLINE][NEWLINE]Develop food, Production, resources and supporting ranged units. Preserve the initial potion until a real objective is reachable. The iron-free Rusher helps the early plan, but the economy still has to build and maintain the force.[NEWLINE][NEWLINE]Stage the existing unembarked melee attackers before drinking. Use ranged fire, siege where appropriate, and controlled paths to maximize productive attacks during the short window. Newly created units do not join that already committed snapshot.[NEWLINE][NEWLINE]Keep a second line and a plan for Aftertaste. Save later bottles for important technologies or fronts rather than using one whenever it becomes available. Normal upgrades preserve only an eligible participant''s remaining deadline.');
