INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_LEADER_TEXT_2','Develop food, Production, resources and supporting ranged units. Preserve the initial potion until a real objective is reachable. The iron-free Rusher helps the early plan, but the economy still has to build and maintain the force.[NEWLINE][NEWLINE]Stage the existing unembarked melee attackers before drinking. Use ranged fire, siege where appropriate, and controlled paths to maximize productive attacks during the short window. Newly created units do not join that already committed snapshot.[NEWLINE][NEWLINE]Keep a second line and a plan for Aftertaste. Save later bottles for important technologies or fronts rather than using one whenever it becomes available. Normal upgrades preserve only an eligible participant''s remaining deadline.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEURGAL_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: A concentrated early strike can punish exposed cities whose owner has prioritized settlement and infrastructure.[NEWLINE][NEWLINE]Viltrum: A well-stocked force can exploit the Scourge''s severe population, survivor and production vulnerability.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: A prepared Toll and territorial line can buy the time needed to exhaust a limited potion window.[NEWLINE][NEWLINE]The Threshold Court: A maintained House network can reinforce a threatened city while the attacking snapshot''s clock keeps running.');
